mapper.select:
SELECT enterprise_id
FROM employee_purchase_activity_enterprises
WHERE company_id = #{companyId}
  AND activity_id = #{activityId}

SELECT e.id AS enterpriseId, e.name, e.enterprise_sn AS enterpriseSn, e.auth_type AS authType, e.distributor_id AS distributorId, e.operator_id AS operatorId FROM employee_purchase_enterprises e INNER JOIN employee_purchase_enterprise_email_box eb ON e.id = eb.enterprise_id WHERE e.company_id = #{companyId} AND eb.suffix = #{suffix}
AND e.id IN
#{eid}
ORDER BY e.id ASC LIMIT 1

SELECT e.id AS enterpriseId, e.name, e.enterprise_sn AS enterpriseSn, e.auth_type AS authType, e.distributor_id AS distributorId, e.operator_id AS operatorId, eb.relay_host AS relayHost, eb.smtp_port AS smtpPort, eb.user AS emailUser, eb.password AS emailPassword FROM employee_purchase_enterprises e INNER JOIN employee_purchase_enterprise_email_box eb ON e.id = eb.enterprise_id WHERE e.company_id = #{companyId} AND eb.suffix = #{suffix}
AND e.distributor_id = #{distributorId}
AND e.id = #{enterpriseId}
ORDER BY e.id ASC LIMIT 1

mapper.sql:
FROM employee_purchase_employees ep
LEFT JOIN employee_purchase_enterprises et ON ep.enterprise_id = et.id
WHERE ep.company_id = #{companyId}
  AND et.auth_type = #{authType}

	AND ep.enterprise_id IN

		#{eid}



	AND ep.enterprise_id = #{singleEnterpriseId}


	AND ep.distributor_id = #{distributorId}


	AND ep.mobile = #{mobileEncrypted}


	AND ep.account = #{account}


	AND ep.auth_code = #{authCode}


	AND (ep.user_id IS NULL OR ep.user_id = 0)
